package net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.stream.Collectors;

import org.apache.commons.text.StringEscapeUtils;

import jakarta.ws.rs.core.Response.ResponseBuilder;

/**
 * HTML helpers for the delegated login pages.
 *
 * Responsibilities: - Render auto-submitted forms with every value escaped. - Build redirect URLs
 * with encoded parameters. - Add the headers shared by these pages.
 *
 * Design notes: - Values come from providers and query strings, so nothing is concatenated without
 * escaping.
 */
public final class DelegatedHtml {

  private DelegatedHtml() {}

  /**
   * Escapes a value for an HTML attribute or text.
   *
   * @param value raw value
   * @return escaped value
   */
  public static String esc(String value) {
    return value == null ? "" : StringEscapeUtils.escapeHtml4(value);
  }

  /**
   * Renders hidden inputs for the given fields.
   *
   * @param fields field names and values
   * @return escaped inputs
   */
  public static String hiddens(Map<String, String> fields) {
    return fields.entrySet().stream().map(e -> "<input type=\"hidden\" name=\"" + esc(e.getKey())
        + "\" value=\"" + esc(e.getValue()) + "\" />").collect(Collectors.joining());
  }

  /**
   * Appends encoded query parameters to a URL that may already have a query.
   *
   * @param url base URL
   * @param params parameters
   * @return URL with the parameters
   */
  public static String withQuery(String url, Map<String, String> params) {
    if (params == null || params.isEmpty()) {
      return url;
    }
    String query = params.entrySet().stream()
        .map(e -> encode(e.getKey()) + "=" + encode(e.getValue())).collect(Collectors.joining("&"));
    return url + (url.contains("?") ? "&" : "?") + query;
  }

  /**
   * Adds the headers of a delegated login page: not cached, no referrer, not framed.
   *
   * @param builder response builder
   * @return the same builder
   */
  public static ResponseBuilder pageHeaders(ResponseBuilder builder) {
    return builder.header("Cache-Control", "no-store").header("Pragma", "no-cache")
        .header("Referrer-Policy", "no-referrer")
        .header("Content-Security-Policy", "frame-ancestors 'none'; base-uri 'none'")
        .header("X-Frame-Options", "DENY");
  }

  /**
   * URL-encodes a value with UTF-8.
   *
   * @param value raw value
   * @return encoded value
   */
  public static String encode(String value) {
    return URLEncoder.encode(value == null ? "" : value, StandardCharsets.UTF_8);
  }
}
